### SPEC-026: Esquemas Zod y Contratos de Datos para Dashboard OTIF Logística

Como Ingeniero de Datos Principal de **maestro_ERP_Pezcaderia**, presento la implementación de los contratos de datos y esquemas de validación en **Zod** para el motor de análisis OTIF (On-Time In-Full) en logística. 

Este diseño garantiza la integridad de los payloads provenientes de las funciones RPC de Supabase y asegura que las vistas materializadas de rendimiento logístico se consuman de manera fuertemente tipada en el frontend (React 18 + Vite).

---

### 1. Contrato de Base de Datos (PostgreSQL / Supabase)

Primero, definimos la estructura analítica subyacente que alimenta el dashboard OTIF. Esto incluye una vista materializada optimizada con índices B-Tree/GIN y una función RPC segura bajo políticas de multi-tenancy estricto (RLS + JWT `app_metadata`).

```sql
-- Esquema de rendimiento logístico y métricas OTIF
CREATE MATERIALIZED VIEW IF NOT EXISTS mv_logistics_otif_metrics AS
SELECT 
    d.tenant_id,
    d.id AS delivery_id,
    d.order_id,
    d.route_id,
    d.driver_id,
    d.committed_at,
    d.delivered_at,
    d.status,
    -- On-Time: Entregado en o antes de la fecha/hora comprometida
    CASE 
        WHEN d.delivered_at <= d.committed_at THEN TRUE 
        ELSE FALSE 
    END AS is_on_time,
    -- In-Full: Sin faltantes ni mermas reportadas respecto al pedido original
    COALESCE(d.items_delivered = d.items_ordered, FALSE) AS is_in_full,
    -- OTIF Completo: Ambas condiciones verdaderas
    CASE 
        WHEN d.delivered_at <= d.committed_at AND COALESCE(d.items_delivered = d.items_ordered, FALSE) THEN TRUE 
        ELSE FALSE 
    END AS is_otif
FROM logistics_deliveries d
WHERE d.status = 'COMPLETED';

-- Índice único para refrescar la vista materializada concurrentemente
CREATE UNIQUE INDEX IF NOT EXISTS idx_mv_logistics_otif_tenant_delivery 
ON mv_logistics_otif_metrics (tenant_id, delivery_id);

-- Índice para consultas por rango de fecha y tenant en el Dashboard
CREATE INDEX IF NOT EXISTS idx_mv_logistics_otif_query_perf 
ON mv_logistics_otif_metrics (tenant_id, committed_at DESC);

-- Función RPC para obtener el resumen OTIF por rangos de fecha con aislamiento Multi-Tenant
CREATE OR REPLACE FUNCTION rpc_get_logistics_otif_summary(
    p_start_date TIMESTAMPTZ,
    p_end_date TIMESTAMPTZ
)
RETURNS TABLE (
    total_deliveries BIGINT,
    on_time_deliveries BIGINT,
    in_full_deliveries BIGINT,
    otif_compliant_deliveries BIGINT,
    otif_percentage NUMERIC(5,2)
) 
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public, pg_temp
AS $$
DECLARE
    v_tenant_id UUID;
BEGIN
    -- Extraer el tenant_id de los metadatos seguros del JWT
    v_tenant_id := NULLIF(current_setting('request.jwt.claim.app_metadata', true)::json->>'tenant_id', '')::UUID;

    IF v_tenant_id IS NULL THEN
        RAISE EXCEPTION 'Acceso denegado: Tenant ID no encontrado en el contexto de seguridad.';
    END IF;

    RETURN QUERY
    SELECT 
        COUNT(*)::BIGINT AS total_deliveries,
        COUNT(*) FILTER (WHERE m.is_on_time IS TRUE)::BIGINT AS on_time_deliveries,
        COUNT(*) FILTER (WHERE m.is_in_full IS TRUE)::BIGINT AS in_full_deliveries,
        COUNT(*) FILTER (WHERE m.is_otif IS TRUE)::BIGINT AS otif_compliant_deliveries,
        CASE 
            WHEN COUNT(*) = 0 THEN 0.00
            ELSE ROUND((COUNT(*) FILTER (WHERE m.is_otif IS TRUE)::NUMERIC / COUNT(*)::NUMERIC) * 100, 2)
        END AS otif_percentage
    FROM mv_logistics_otif_metrics m
    STRICT
    WHERE m.tenant_id = v_tenant_id
      AND m.committed_at >= p_start_date
      AND m.committed_at <= p_end_date;
END;
$$;

-- Otorgar permisos de ejecución al rol autenticado
GRANT EXECUTE ON FUNCTION rpc_get_logistics_otif_summary(TIMESTAMPTZ, TIMESTAMPTZ) TO authenticated;
```

