### 2. Esquemas Zod (TypeScript - Data Contracts)

A continuación, implementamos los contratos de datos en TypeScript utilizando **Zod**. Estos esquemas validan tanto los parámetros de entrada hacia la capa de servicios como las respuestas serializadas devueltas por Supabase.

```typescript
import { z } from 'zod';

/**
 * Esquema de validación para los parámetros de consulta del Dashboard OTIF.
 */
export const GetOtifSummaryParamsSchema = z.object({
  startDate: z.string().datetime({ message: 'La fecha de inicio debe tener formato ISO 8601 válido.' }),
  endDate: z.string().datetime({ message: 'La fecha de fin debe tener formato ISO 8601 válido.' }),
}).refine((data) => new Date(data.startDate) <= new Date(data.endDate), {
  message: 'La fecha de inicio no puede ser posterior a la fecha de fin.',
  path: ['startDate'],
});

export type GetOtifSummaryParams = z.infer<typeof GetOtifSummaryParamsSchema>;

/**
 * Esquema de validación para el payload de respuesta de la RPC rpc_get_logistics_otif_summary.
 */
export const OtifSummaryResponseSchema = z.object({
  totalDeliveries: z.number().int().nonnegative(),
  onTimeDeliveries: z.number().int().nonnegative(),
  inFullDeliveries: z.number().int().nonnegative(),
  otifCompliantDeliveries: z.number().int().nonnegative(),
  otifPercentage: z.number().min(0).max(100),
});

export type OtifSummaryResponse = z.infer<typeof OtifSummaryResponseSchema>;

/**
 * Esquema detallado por entrega individual para tablas de auditoría logística.
 */
export const LogisticsDeliveryItemSchema = z.object({
  tenantId: z.string().uuid(),
  deliveryId: z.string().uuid(),
  orderId: z.string().uuid(),
  routeId: z.string().uuid().nullable(),
  driverId: z.string().uuid().nullable(),
  committedAt: z.string().datetime(),
  deliveredAt: z.string().datetime().nullable(),
  status: z.enum(['PENDING', 'IN_TRANSIT', 'COMPLETED', 'FAILED', 'CANCELLED']),
  isOnTime: z.boolean(),
  isInFull: z.boolean(),
  isOtif: z.boolean(),
});

export type LogisticsDeliveryItem = z.infer<typeof LogisticsDeliveryItemSchema>;
```

