### 3. Servicio de Integración Frontend (Supabase Client Adapter)

Este adaptador utiliza los esquemas Zod definidos para garantizar que los datos consumidos desde el cliente cumplan estrictamente con el contrato antes de ser inyectados en los componentes de UI del Dashboard OTIF.

```typescript
import { createClient } from '@supabase/supabase-js';
import { 
  GetOtifSummaryParamsSchema, 
  OtifSummaryResponseSchema, 
  type GetOtifSummaryParams, 
  type OtifSummaryResponse 
} from './otif.schema';

// Instancia tipada del cliente de Supabase (asume entorno configurado)
const supabaseUrl = import.meta.env.VITE_SUPABASE_URL;
const supabaseAnonKey = import.meta.env.VITE_SUPABASE_ANON_KEY;
export const supabase = createClient(supabaseUrl, supabaseAnonKey);

/**
 * Servicio logístico para consultar métricas OTIF con validación Zod estricta.
 */
export async function fetchLogisticsOtifSummary(params: GetOtifSummaryParams): Promise<OtifSummaryResponse> {
  // 1. Validar parámetros de entrada en el cliente antes de invocar la red
  const validatedParams = GetOtifSummaryParamsSchema.parse(params);

  // 2. Invocar la función RPC en PostgreSQL
  const { data, error } = await supabase.rpc('rpc_get_logistics_otif_summary', {
    p_start_date: validatedParams.startDate,
    p_end_date: validatedParams.endDate,
  });

  if (error) {
    throw new Error(`Error en RPC rpc_get_logistics_otif_summary: ${error.message}`);
  }

  // La función RPC retorna un array de 1 registro o vacío
  const rawResult = Array.isArray(data) ? data[0] : data;

  if (!rawResult) {
    // Retornar valores por defecto si no existen registros en el rango
    return {
      totalDeliveries: 0,
      onTimeDeliveries: 0,
      inFullDeliveries: 0,
      otifCompliantDeliveries: 0,
      otifPercentage: 0.00,
    };
  }

  // Mapeo de snake_case (DB) a camelCase (TypeScript) si es necesario, 
  // o validación directa si el objeto coincide. Aquí normalizamos:
  const normalizedData = {
    totalDeliveries: Number(rawResult.total_deliveries),
    onTimeDeliveries: Number(rawResult.on_time_deliveries),
    inFullDeliveries: Number(rawResult.in_full_deliveries),
    otifCompliantDeliveries: Number(rawResult.otif_compliant_deliveries),
    otifPercentage: Number(rawResult.otif_percentage),
  };

  // 3. Validar el contrato de salida con Zod
  const validatedResponse = OtifSummaryResponseSchema.parse(normalizedData);

  return validatedResponse;
}
